sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.continueLogin = function() {

        var role = c.data.role;

        sessionStorage.setItem(
            "cfms_selected_role",
            role
        );

        window.location.href =
            "?id=login&sysparm_url=%3Fid%3Dcfms_role_router";
    };


    c.back = function() {

        window.location.href =
            "?id=cfms_home";

    };

};

sp_widget.css:
/* =========================================
   CFMS - MAIN SITE
   ========================================= */

.cfms-site {
    width: 100%;
    min-height: 100vh;
    margin: 0;
    padding: 0;
    font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
    color: #263238;
    background: #f0fbfc;
}


/* =========================================
   NAVIGATION BAR
   ========================================= */

.main-nav {
    width: 100%;
    min-height: 72px;

    display: flex;
    align-items: center;
    justify-content: space-between;

    padding: 0 55px;
    box-sizing: border-box;

    background: #00acc1;
    color: white;

    position: relative;
    z-index: 1000;
}

.nav-logo-container {
    display: flex;
    align-items: center;

    color: white;
    font-size: 26px;
    font-weight: 700;

    cursor: pointer;
}

.nav-app-logo {
    width: 42px;
    height: 42px;

    margin-right: 10px;

    border-radius: 10px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: white;
    color: #00acc1;

    font-size: 22px;
}


/* NAV LINKS */

.nav-links {
    display: flex;
    align-items: center;

    gap: 30px;

    margin: 0;
    padding: 0;

    list-style: none;
}

.nav-links li {
    position: relative;
}

.nav-links li > a {
    color: white !important;

    text-decoration: none !important;

    font-size: 15px;
    font-weight: 500;

    cursor: pointer;

    transition: 0.2s ease;
}

.nav-links li > a:hover {
    opacity: 0.8;
}


/* =========================================
   LOGIN DROPDOWN
   ========================================= */

.dropdown {
    position: relative;
}

.dropbtn {
    display: flex;
    align-items: center;

    gap: 7px;

    padding: 10px 15px;

    border-radius: 7px;

    background: white;

    color: #00acc1 !important;

    font-weight: 600 !important;
}

.dropbtn:hover {
    background: #e0f7fa;
    opacity: 1 !important;
}


.dropdown-content {
    display: none;

    position: absolute;

    right: 0;
    top: 43px;

    width: 215px;

    background: white;

    border-radius: 10px;

    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.18);

    overflow: hidden;

    z-index: 9999;
}

.dropdown:hover .dropdown-content {
    display: block;
}

.dropdown-content a {
    display: flex;
    align-items: center;

    gap: 12px;

    padding: 14px 17px;

    color: #263238 !important;

    background: white;

    text-decoration: none !important;

    font-size: 14px;

    cursor: pointer;

    transition: 0.2s ease;
}

.dropdown-content a:hover {
    background: #e0f7fa;

    color: #00acc1 !important;
}

.dropdown-content a i {
    width: 20px;

    text-align: center;

    color: #00acc1;
}


/* =========================================
   HERO SECTION
   ========================================= */

.hero-section {
    width: 100%;
    min-height: 480px;

    display: flex;
    align-items: center;
    justify-content: space-between;

    box-sizing: border-box;

    padding: 70px 9%;

    background: #4dd0e1;

    gap: 60px;
}


/* HERO LEFT */

.hero-content {
    flex: 1;

    max-width: 650px;
}

.hero-title {
    margin: 0 0 25px 0;

    color: #263238;

    font-size: 58px;

    line-height: 1.05;

    font-weight: 750;

    letter-spacing: -1px;
}

.hero-title span {
    color: white;
}

.hero-subtitle {
    max-width: 600px;

    margin: 0 0 28px 0;

    color: #37474f;

    font-size: 17px;

    line-height: 1.7;
}


/* GET STARTED BUTTON */

.cta-btn {
    display: inline-flex;

    align-items: center;

    gap: 10px;

    padding: 14px 25px;

    background: #00acc1;

    color: white !important;

    border-radius: 8px;

    text-decoration: none !important;

    font-size: 15px;

    font-weight: 600;

    cursor: pointer;

    transition: all 0.25s ease;
}

.cta-btn:hover {
    background: #008fa1;

    color: white !important;

    transform: translateY(-2px);

    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.15);
}


/* =========================================
   HERO APP INFO
   ========================================= */

.hero-app-info {
    flex: 0 0 390px;

    padding: 30px;

    box-sizing: border-box;

    background: rgba(255, 255, 255, 0.95);

    border-radius: 18px;

    box-shadow: 0 15px 35px rgba(0, 0, 0, 0.12);

    border: 1px solid rgba(255, 255, 255, 0.7);
}

.hero-app-info h3 {
    display: flex;

    align-items: center;

    gap: 10px;

    margin: 0 0 18px 0;

    color: #00acc1;

    font-size: 21px;
}

.hero-app-info h3 i {
    font-size: 25px;
}

.hero-app-info p {
    margin: 0 0 14px 0;

    color: #546e7a;

    font-size: 14px;

    line-height: 1.7;
}

.hero-app-info strong {
    color: #263238;
}


/* =========================================
   FEATURES
   ========================================= */

.features-row {
    width: 100%;

    display: grid;

    grid-template-columns: repeat(4, 1fr);

    gap: 24px;

    padding: 65px 9%;

    box-sizing: border-box;

    background: #f0fbfc;
}


.feature-card {
    background: white;

    padding: 30px 22px;

    text-align: center;

    border-radius: 15px;

    border: 1px solid #e1f2f4;

    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.07);

    transition: all 0.25s ease;
}

.feature-card:hover {
    transform: translateY(-7px);

    box-shadow: 0 14px 30px rgba(0, 0, 0, 0.12);
}


/* FEATURE ICON */

.feature-icon {
    width: 65px;
    height: 65px;

    margin: 0 auto 18px auto;

    border-radius: 50%;

    display: flex;

    align-items: center;
    justify-content: center;

    font-size: 27px;
}

.icon-teal {
    background: #e0f7fa;
    color: #00acc1;
}

.icon-blue {
    background: #e1f5fe;
    color: #0288d1;
}

.icon-yellow {
    background: #fff8e1;
    color: #f9a825;
}

.icon-red {
    background: #ffebee;
    color: #e53935;
}


.feature-card h4 {
    margin: 0 0 12px 0;

    color: #263238;

    font-size: 18px;

    font-weight: 650;
}

.feature-card p {
    margin: 0;

    color: #546e7a;

    font-size: 14px;

    line-height: 1.6;
}


/* =========================================
   ABOUT SECTION
   ========================================= */

.about-section {
    width: 100%;

    padding: 80px 9%;

    box-sizing: border-box;

    background: white;

    text-align: center;
}

.about-label {
    display: inline-block;

    padding: 7px 15px;

    border-radius: 20px;

    background: #e0f7fa;

    color: #00acc1;

    font-size: 13px;

    font-weight: 600;
}

.about-title {
    margin: 18px 0;

    color: #263238;

    font-size: 38px;

    line-height: 1.2;

    font-weight: 700;
}

.about-text {
    max-width: 720px;

    margin: 0 auto;

    color: #546e7a;

    font-size: 16px;

    line-height: 1.8;
}


/* =========================================
   STATISTICS
   ========================================= */

.stats-grid {
    max-width: 1000px;

    margin: 55px auto 0 auto;

    display: grid;

    grid-template-columns: repeat(4, 1fr);

    gap: 25px;
}

.stat-item {
    padding: 25px 15px;

    border-radius: 12px;

    background: #f0fbfc;
}

.stat-item i {
    font-size: 25px;

    color: #00acc1;

    margin-bottom: 10px;
}

.stat-item h3 {
    margin: 5px 0;

    color: #263238;

    font-size: 25px;
}

.stat-item p {
    margin: 0;

    color: #546e7a;

    font-size: 13px;
}


/* =========================================
   FOOTER
   ========================================= */

.main-footer {
    width: 100%;

    background: #00acc1;

    color: white;
}

.footer-content {
    display: grid;

    grid-template-columns: 2fr 1fr 1.5fr;

    gap: 50px;

    padding: 50px 9%;

    box-sizing: border-box;
}


/* FOOTER LOGO */

.footer-logo {
    display: flex;

    align-items: center;

    gap: 10px;

    margin-bottom: 15px;

    font-size: 24px;

    font-weight: 700;
}

.footer-logo i {
    font-size: 25px;
}

.footer-col p {
    margin: 8px 0;

    color: rgba(255, 255, 255, 0.9);

    font-size: 14px;

    line-height: 1.6;
}


/* FOOTER HEADINGS */

.footer-col h3 {
    margin: 0 0 17px 0;

    color: white;

    font-size: 18px;
}


/* FOOTER LINKS */

.footer-col ul {
    margin: 0;
    padding: 0;

    list-style: none;
}

.footer-col ul li {
    margin-bottom: 10px;
}

.footer-col ul li a {
    color: rgba(255, 255, 255, 0.9) !important;

    text-decoration: none !important;

    font-size: 14px;

    cursor: pointer;
}

.footer-col ul li a:hover {
    color: white !important;

    text-decoration: underline !important;
}


/* SUPPORT ICONS */

.footer-col p i {
    width: 20px;

    margin-right: 6px;

    text-align: center;
}


/* =========================================
   FOOTER BOTTOM
   ========================================= */

.footer-bottom {
    padding: 18px 20px;

    border-top: 1px solid rgba(255, 255, 255, 0.2);

    text-align: center;

    color: rgba(255, 255, 255, 0.85);

    font-size: 13px;
}


/* =========================================
   TABLET
   ========================================= */

@media (max-width: 1000px) {

    .main-nav {
        padding: 0 25px;
    }

    .nav-links {
        gap: 16px;
    }

    .hero-section {
        padding: 60px 6%;
    }

    .hero-title {
        font-size: 46px;
    }

    .hero-app-info {
        flex-basis: 330px;
    }

    .features-row {
        padding: 55px 6%;
        grid-template-columns: repeat(2, 1fr);
    }

    .stats-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .footer-content {
        padding: 45px 6%;
    }
}


/* =========================================
   MOBILE
   ========================================= */

@media (max-width: 700px) {

    .main-nav {
        min-height: auto;

        padding: 18px 20px;

        flex-direction: column;

        gap: 18px;
    }

    .nav-links {
        flex-wrap: wrap;

        justify-content: center;

        gap: 15px;
    }

    .hero-section {
        flex-direction: column;

        padding: 55px 25px;

        text-align: center;
    }

    .hero-content {
        width: 100%;
    }

    .hero-title {
        font-size: 40px;
    }

    .hero-subtitle {
        font-size: 15px;
    }

    .hero-app-info {
        width: 100%;

        flex: auto;

        text-align: left;
    }

    .features-row {
        grid-template-columns: 1fr;

        padding: 50px 25px;
    }

    .about-section {
        padding: 60px 25px;
    }

    .about-title {
        font-size: 30px;
    }

    .stats-grid {
        grid-template-columns: 1fr 1fr;
    }

    .footer-content {
        grid-template-columns: 1fr;

        gap: 30px;

        padding: 40px 25px;
    }
}


/* =========================================
   SMALL MOBILE
   ========================================= */

@media (max-width: 450px) {

    .nav-logo-container {
        font-size: 22px;
    }

    .nav-links {
        gap: 10px;
    }

    .nav-links li > a {
        font-size: 13px;
    }

    .hero-title {
        font-size: 34px;
    }

    .hero-app-info {
        padding: 23px;
    }

    .stats-grid {
        grid-template-columns: 1fr;
    }
}

sp_widget.script:
(function() {

    var role =
        $sp.getParameter("role");


    if (!role) {

        role = "student";

    }


    data.role = role;


    if (role == "student") {

        data.roleName = "Student";

        data.icon =
            "fa fa-graduation-cap";

    }


    else if (role == "staff") {

        data.roleName = "Staff";

        data.icon =
            "fa fa-user";

    }


    else if (role == "manager") {

        data.roleName = "Manager";

        data.icon =
            "fa fa-briefcase";

    }


    else if (role == "admin") {

        data.roleName = "Admin";

        data.icon =
            "fa fa-shield";

    }

})();
